urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) and file.page.url != 'tools/' %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.update_date %}{{file.page.update_date}}{% endif %}

    {%- endif -%}
{% endfor %}
{#- Standalone HTML tools are nav pages built from .html files, which the default loop skips: list them too (Chess is private, left out) -#}
{%- for item in nav recursive -%}
  {%- if item.children -%}{{ loop(item.children) }}
  {%- elif item.is_page and item.file and item.file.src_uri.endswith('.html') and 'chess' not in item.url %}

         {{ (config.site_url ~ item.url)|e }}

  {%- endif -%}
{%- endfor %}
